import {setupGroupTags} from './group-tags.mjs';import {workspaceDocument} from '../../../shared/workspace-domain.ts';
export async function setupRelativeTags(t,options={}){const x=await setupGroupTags(t,options),id=crypto.randomUUID(),source=(await x.exported()).document;source.savedTaskViews=[{id,revision:1,isArchived:false,name:'Day-bound exact list',query:{source:'tasks',filter:{plannedRelative:'noDate'},timeZoneId:'Pacific/Kiritimati'}}];const document=workspaceDocument(source);await x.f.workspaceDb.prepare('UPDATE workspaces SET document_json=?').bind(JSON.stringify(document)).run();return Object.assign(x,{id});}
